import{_ as e,o as a,c as r,a4 as o}from"./chunks/framework.B0hSrcZ6.js";const s="/info/25-faq.webp",l="/info/25-faq-s2.webp",n="/info/25-faq-s3.webp",i="/info/25-faq-s4.webp",f=JSON.parse('{"title":"第 25 章 常见问题与排错","description":"本章系统整理 Grok Bot 的常见问题与排错步骤。涵盖登录认证、环境恢复、例程报错及用量异常排查，指导读者有序定位故障原因，避免盲目重装导致配置环境丢失。","frontmatter":{},"headers":[],"relativePath":"part4/25-faq.md","filePath":"part4/25-faq.md","lastUpdated":1792419518000}'),d={name:"part4/25-faq.md"};function h(p,t,c,g,u,b){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="第-25-章-常见问题与排错" tabindex="-1">第 25 章 常见问题与排错 <a class="header-anchor" href="#第-25-章-常见问题与排错" aria-label="Permalink to &quot;第 25 章 常见问题与排错&quot;">​</a></h1><p>遇到报错或卡顿，<strong>千万别盲目重装或重置</strong>，这会冲掉刚写好的环境和临时脚本。</p><ol><li><strong>先看服务状态</strong>。</li><li>再排查是本地网络、插件授权、云端环境还是每周额度的问题。</li></ol><p><img src="'+s+'" alt="常见问题与排错" width="1600" height="1013" decoding="async"></p><h2 id="登录与身份验证" tabindex="-1">Grok Bot 登录与绑定账号出问题怎么办？ <a class="header-anchor" href="#登录与身份验证" aria-label="Permalink to &quot;Grok Bot 登录与绑定账号出问题怎么办？ {#登录与身份验证}&quot;">​</a></h2><p><strong>个人用户通过设置页面或专用链接关联授权，企业席位直接用 Grok 登录，若绑错需找人工客服，遇循环跳回可清 Cookie 用无痕模式认证。</strong></p><h3 id="账号与订阅限制" tabindex="-1">账号与订阅限制 <a class="header-anchor" href="#账号与订阅限制" aria-label="Permalink to &quot;账号与订阅限制&quot;">​</a></h3><p>Grok Bot 依托 Cursor 运行，与 Grok 手机端付费墙及每周额度限制（Weekly SuperGrok Limit）无关。</p><p>个人版支持 SuperGrok 与 Plus、Heavy 版本，以及 X Premium+；SuperGrok Lite 与 Grok Enterprise 无法关联个人账户，企业席位由管理员统一分配。</p><p><strong>账户邮箱注册后无法修改，关联 Cursor 是一次性永久绑定</strong>。绑错账号无法自行转移，必须联系人工客服处理。</p><h3 id="绑定与登录步骤" tabindex="-1">绑定与登录步骤 <a class="header-anchor" href="#绑定与登录步骤" aria-label="Permalink to &quot;绑定与登录步骤&quot;">​</a></h3><ol><li><p>个人绑定：打开 <a href="https://cursor.com/bot/onboarding" target="_blank" rel="noreferrer">cursor.com/bot/onboarding</a> 或在客户端进入 <strong>设置</strong> &gt; <strong>用量和计费</strong>，在 <strong>管理方案</strong> 下点击 <strong>通过 Grok 获取访问权限</strong>（仅在能提升当前用量层级时显示）。</p></li><li><p>企业席位：拥有 Grok Business 席位无需在方案页手动绑定，完全退出后在登录页点击 <strong>Sign in with Grok</strong> 即可。</p></li><li><p>服务确认：遇到异常先访问 <a href="https://status.cursor.com" target="_blank" rel="noreferrer">status.cursor.com</a> 查看 <strong>Grok Bot</strong> 实时状态，操作要求详见<a href="https://cursor.com/cn/help/grok-bot/sign-in" target="_blank" rel="noreferrer">登录 Grok Bot</a>。</p><p><strong>服务故障时等待官方修复，切勿重装应用或重置电脑</strong>。</p></li></ol><h3 id="故障排查与验收" tabindex="-1">故障排查与验收 <a class="header-anchor" href="#故障排查与验收" aria-label="Permalink to &quot;故障排查与验收&quot;">​</a></h3><p>客户端版本过旧会引发协议不匹配；突发认证故障建议静置 30 到 60 分钟再试。<strong>验收标准是账号邮箱、订阅归属与客户端登录状态一一对应</strong>。</p><table tabindex="0"><thead><tr><th style="text-align:left;">故障现象</th><th style="text-align:left;">正确处置路径</th><th style="text-align:left;">严禁操作</th></tr></thead><tbody><tr><td style="text-align:left;">循环跳回登录页</td><td style="text-align:left;">清理 <code>cursor.com</code> 与 <code>x.ai</code> 的 Cookie，用桌面端无痕模式认证</td><td style="text-align:left;">连续卸载重装客户端</td></tr><tr><td style="text-align:left;">找不到关联入口</td><td style="text-align:left;">确认当前账号层级低于待绑定方案，未达上限</td><td style="text-align:left;">注册新账号重复购买</td></tr><tr><td style="text-align:left;">提示 Model provider is overloaded</td><td style="text-align:left;">复制报错的 Request ID，等待 2 分钟重新发送</td><td style="text-align:left;">立即点击 Reset 重置电脑</td></tr><tr><td style="text-align:left;">提示邮箱需变更</td><td style="text-align:left;">重新注册账号并迁移资产</td><td style="text-align:left;">尝试在设置中强改绑定邮箱</td></tr></tbody></table><p>向 Bot 发送提示词确认登录状态。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请检查当前运行环境的网络连通性与 Cursor 身份验证状态，汇报当前登录的用户环境标识，但不要输出任何敏感 Token。</span></span></code></pre></div><h2 id="云端电脑与环境恢复" tabindex="-1">Grok Bot 连不上云端电脑该如何恢复？ <a class="header-anchor" href="#云端电脑与环境恢复" aria-label="Permalink to &quot;Grok Bot 连不上云端电脑该如何恢复？ {#云端电脑与环境恢复}&quot;">​</a></h2><p><strong>遇到断连可先等两分钟重试或彻底重启应用，卡死时点 Recover 存现场重建，而会覆盖快照丢失未同步修改的 Reset 只能作最后兜底手段。</strong></p><p><img src="'+l+'" alt="云端电脑与环境恢复" width="1600" height="1013" loading="lazy" decoding="async"></p><p>所有 Bot 共享同一台云端电脑。<strong>对话记录独立存在数据库</strong>，崩溃清空都不丢。</p><p>提示 Reconnecting、Couldn&#39;t Reach Grok Bot&#39;s Computer 或 Bot failed to respond 时：</p><ol><li>等 1 到 2 分钟点 Retry。</li><li>彻底退出应用。Mac 按 <code>Cmd+Q</code>，Win/Linux 退出托盘，别只关窗口。</li><li>进设置 &gt; 计算机点更新。备份未完或 Bot 工作时切勿中断。</li><li>卡住点 Recover。</li><li><strong>Reset 是最后手段</strong>。快照覆盖会丢未同步修改。详见<a href="https://cursor.com/cn/help/grok-bot/computer-recovery" target="_blank" rel="noreferrer">Grok Bot 电脑</a>。</li></ol><table tabindex="0"><thead><tr><th>操作</th><th>现场保存</th><th>环境影响</th><th>场景</th></tr></thead><tbody><tr><td>Retry</td><td>原样保留</td><td>无影响</td><td>网络抖动</td></tr><tr><td>Update</td><td>等备份完</td><td>全留软件；整机清自装包</td><td>官方补丁</td></tr><tr><td>Recover</td><td>存现场建机</td><td>移除自装应用与环境</td><td>卡死损坏</td></tr><tr><td>Reset</td><td>快照覆盖</td><td>丢未同步修改</td><td>连不上兜底</td></tr></tbody></table><p><strong>电脑状态变绿显示已连接</strong>、终端正常且配置完整就算修好。</p><ul><li>遇到 SSO 登录，点卡片上的 Take over 手动验证，搞定点 I&#39;m done。</li><li>密钥与网络：在设置 &gt; General &gt; Security Key 开 Use hardware security keys 插 YubiKey；遇验证码在设置 &gt; 计算机勾“通过此计算机路由流量”。</li><li>本地执行：在设置 &gt; 计算机开“在此计算机上执行”（跑命令先确认）。详见<a href="https://cursor.com/cn/docs/grok-bot/settings" target="_blank" rel="noreferrer">Grok Bot 设置</a>。</li><li>磁盘告警：报 Computer is low on disk space 时点 Go to Disk Saver，<strong>必须人工确认才删</strong>。</li></ul><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请检查当前云端计算机根目录与工作目录的磁盘占用情况，找出体积超过 200MB 的文件与缓存目录，列出清单供我确认，不要擅自执行任何删除命令。</span></span></code></pre></div><h2 id="例程管理与自动化排错" tabindex="-1">Grok Bot 自动化例程不触发该怎么排错？ <a class="header-anchor" href="#例程管理与自动化排错" aria-label="Permalink to &quot;Grok Bot 自动化例程不触发该怎么排错？ {#例程管理与自动化排错}&quot;">​</a></h2><p><strong>例程无动静先确认状态非暂停并校对时区与 Test 测试，Webhook 需带鉴权密钥且 200 仅代表入队，Slack 触发必须限定频道白名单与过滤词。</strong></p><p><img src="'+n+'" alt="例程管理与自动化排错" width="1600" height="1013" loading="lazy" decoding="async"></p><p>例程在云端自动跑，关机也生效，支持定时、Webhook 与 Slack 推送。</p><ol><li><strong>查状态与时区</strong>：Details 确认非 <strong>Paused</strong>（手机看 <strong>Active</strong>）；在“设置 &gt; Bot &gt; Timezone”手动选时区，跨国别用 Auto-detect。</li><li><strong>定时触发时机</strong>：只等下个周期（09:05 设 09:00 明早跑），即时测逻辑点 <strong>Test</strong>。</li><li><strong>校验 Webhook</strong>：POST 带 <code>Authorization: Bearer &lt;key&gt;</code>。<strong>200 仅代表入队</strong>，结果去聊天窗口看；非 200 为密钥错或暂停。</li><li><strong>收窄 Slack 触发</strong>：<strong>必须限频道与过滤词</strong>，防闲聊几小时烧光配额。详见<a href="https://cursor.com/cn/help/grok-bot/routines" target="_blank" rel="noreferrer">例程</a>。</li></ol><p>手机端“运行历史”查 <strong>Running</strong>、<strong>Succeeded</strong>、<strong>Failed</strong>；显示 <strong>No runs yet</strong> 为未触发。</p><table tabindex="0"><thead><tr><th>故障</th><th>原因</th><th>修复</th></tr></thead><tbody><tr><td>无动静</td><td>Paused/未到点/时区偏差</td><td>查 Active，点 Test，校对 Timezone</td></tr><tr><td>401/403</td><td>漏 Token/密钥重置/例程已删</td><td>重新复制 header 覆盖配置</td></tr><tr><td>Slack 无回应</td><td>旧消息/频道或词未命中</td><td>只认新消息，核对频道白名单与短语</td></tr><tr><td>配额消耗快</td><td>间隔过短/大群无过滤词</td><td>暂停例程，拉长间隔，限定运维频道</td></tr></tbody></table><p>创建与修正自动化例程提示词：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请修改名为“工单同步”的例程：仅在 #ops-alert 频道出现包含“[P0-Error]”文字的新消息时才触发，忽略其他日常聊天，并列出更新后的 When to run 描述。</span></span></code></pre></div><h2 id="用量异常与配额控制" tabindex="-1">用量异常与配额控制 <a class="header-anchor" href="#用量异常与配额控制" aria-label="Permalink to &quot;用量异常与配额控制&quot;">​</a></h2><p><img src="'+i+`" alt="用量异常与配额控制" width="1600" height="1013" loading="lazy" decoding="async"></p><p>Grok Bot 配额按周重置。基础额度用完会中断回复，<strong>这属于正常的配额熔断</strong>。一次性试用额度跑复杂任务耗尽后无法恢复。</p><h3 id="操作与防坑" tabindex="-1">操作与防坑 <a class="header-anchor" href="#操作与防坑" aria-label="Permalink to &quot;操作与防坑&quot;">​</a></h3><ol><li>恢复额度：等每周刷新，或在 <strong>设置</strong> &gt; <strong>用量和计费</strong> 开按需用量，也可升订阅。</li><li>设定封顶：客户端或网页 <a href="https://cursor.com/dashboard" target="_blank" rel="noreferrer">cursor.com/dashboard</a> 设限。<strong>在跑任务不强切，扣费微超几个百分点属正常。</strong></li><li>额度对齐：外部账号不叠加取高者（Pro 对应 SuperGrok/X Premium+，Pro+ 对应 SuperGrok Plus，Ultra 对应 SuperGrok Heavy）。</li><li>移动端退订：多端共享订阅。商店付款需在 Apple ID 或 Google Play 退，官方不直退，见<a href="https://cursor.com/cn/help/grok-bot/plans" target="_blank" rel="noreferrer">方案和计费</a>。</li></ol><h3 id="验收标准" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准" aria-label="Permalink to &quot;验收标准&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">场景</th><th style="text-align:left;">操作</th><th style="text-align:left;">边界与坑点</th></tr></thead><tbody><tr><td style="text-align:left;">防超额</td><td style="text-align:left;">客户端或控制台设月度限额</td><td style="text-align:left;"><strong>封顶拒新请求，在跑任务跑完才停</strong></td></tr><tr><td style="text-align:left;">查用量</td><td style="text-align:left;">Bot 内部设置查实时剩余</td><td style="text-align:left;">外部 Grok 看板不互通</td></tr><tr><td style="text-align:left;">试用清零</td><td style="text-align:left;">排查大工程扫描或重构</td><td style="text-align:left;">一次性耗尽不恢复</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请列出你当前账号下所有处于活跃状态的例程，评估它们各自的执行频率与触发条件，指出哪一个例程最容易引发高额用量消耗。</span></span></code></pre></div><h2 id="群聊、协作与辅助-bot-治理" tabindex="-1">群聊、协作与辅助 Bot 治理 <a class="header-anchor" href="#群聊、协作与辅助-bot-治理" aria-label="Permalink to &quot;群聊、协作与辅助 Bot 治理&quot;">​</a></h2><p>辅助 Bot 会进侧边栏并弹通知，改文件或连外网会触发 <strong>Auto-review</strong> 审批。</p><h3 id="操作与审批" tabindex="-1">操作与审批 <a class="header-anchor" href="#操作与审批" aria-label="Permalink to &quot;操作与审批&quot;">​</a></h3><ol><li><p>降噪隐藏：桌面端右键选 Hide from sidebar 或发指令关通知；手机端进配置关通知。</p></li><li><p>恢复误藏：桌面在 <strong>隐藏的机器人</strong> 选 Show in sidebar，手机选 Unhide。<strong>严禁为找 Bot 去点云端 Recover 或 Reset。</strong></p></li><li><p>审批与白名单：高频操作点 <strong>始终允许</strong>（存入 设置 &gt; Bot &gt; 自定义规则）；冲突先询问，显示“由管理员强制要求”的不可跳过。</p><p>规范见 <a href="https://cursor.com/cn/help/grok-bot/how-to" target="_blank" rel="noreferrer">Grok Bot 操作指南</a>。</p></li></ol><h3 id="验收标准-1" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准-1" aria-label="Permalink to &quot;验收标准&quot;">​</a></h3><p>侧边栏无杂乱 Bot，日常高频<strong>免打扰自动通过</strong>。</p><table tabindex="0"><thead><tr><th>场景</th><th>超时</th><th>表现</th><th>对策</th></tr></thead><tbody><tr><td>前台人工</td><td>永久等待</td><td>持续挂起</td><td>核对后允许或拒绝</td></tr><tr><td>后台/Webhook</td><td>约 10 分钟</td><td>变 Expired 取消</td><td>配“始终允许”或开通知</td></tr><tr><td>管理员强制</td><td>视场景</td><td>无法跳过</td><td>必须人工授权</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请梳理我们在此会话中频繁执行的文件读取与构建指令，为它们生成一组最小权限的安全规则建议，以便我添加到 Auto-review 的自定义白名单中。</span></span></code></pre></div><h2 id="插件与外部应用连接" tabindex="-1">插件与外部应用连接 <a class="header-anchor" href="#插件与外部应用连接" aria-label="Permalink to &quot;插件与外部应用连接&quot;">​</a></h2><h3 id="授权排错" tabindex="-1">授权排错 <a class="header-anchor" href="#授权排错" aria-label="Permalink to &quot;授权排错&quot;">​</a></h3><p><strong>Added 只表示已安装，不等于已登录</strong>。卡片没弹去侧边栏手动验证。<strong>授权须在 10 分钟内完成</strong>，超时点 Reopen；持续报错点 Remove 删掉重装。</p><table tabindex="0"><thead><tr><th style="text-align:left;">状态</th><th style="text-align:left;">处理</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Added / Needs auth</strong></td><td style="text-align:left;">点「验证身份」去浏览器登录</td></tr><tr><td style="text-align:left;"><strong>Connected 报错</strong></td><td style="text-align:left;">发送带插件名的指令刷新会话</td></tr><tr><td style="text-align:left;"><strong>Disabled by team admin</strong></td><td style="text-align:left;">找团队管理员解禁</td></tr></tbody></table><h3 id="多账号与验收" tabindex="-1">多账号与验收 <a class="header-anchor" href="#多账号与验收" aria-label="Permalink to &quot;多账号与验收&quot;">​</a></h3><ol><li><strong>多账号</strong>：在「连接应用」&gt; 插件 &gt; Accounts 点 <strong>Add Another Account</strong>（手机端点 Authorize new account）并打标签。对话指明标签调用；无按钮则仅支持单账号。</li><li><strong>验收</strong>：<strong>状态显示绿色 Connected 且标签清晰</strong>，发指令能一次准确调用。</li></ol><p>详见<a href="https://cursor.com/cn/help/grok-bot/connect-plugins" target="_blank" rel="noreferrer">连接插件</a>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请刷新当前已连接的插件列表，使用带有“工作”标签的账户连接，读取最近更新的 3 个页面，确认授权是否正常。</span></span></code></pre></div><h2 id="账号注销与数据清理" tabindex="-1">账号注销与数据清理 <a class="header-anchor" href="#账号注销与数据清理" aria-label="Permalink to &quot;账号注销与数据清理&quot;">​</a></h2><p>Grok Bot 共用 Cursor 账号，<strong>删号不可逆</strong>，无法单独保留 Cursor。换电脑用直接退出登录或卸载就行。</p><h3 id="终端注销步骤" tabindex="-1">终端注销步骤 <a class="header-anchor" href="#终端注销步骤" aria-label="Permalink to &quot;终端注销步骤&quot;">​</a></h3><p>注销前务必取消自动续费，避免账单纠纷。</p><ol><li>手机端（iOS/Android）：点头像进“设置” &gt; 账户信息 &gt;“删除账户”，网页验证中键入“<strong>删除</strong>”两字确认。</li><li>桌面与网页端：<strong>客户端无法直接注销</strong>。登录 <a href="https://cursor.com/dashboard" target="_blank" rel="noreferrer">cursor.com/dashboard</a> &gt;“设置” &gt;“更多” &gt;“删除账户”确认。</li><li>企业或团队席位：个人无法独立注销，必须联系管理员解绑或提工单。条款见<a href="https://cursor.com/cn/help/grok-bot/delete-account" target="_blank" rel="noreferrer">删除你的 Grok Bot 账户</a>。</li></ol><h3 id="资产清理与避坑" tabindex="-1">资产清理与避坑 <a class="header-anchor" href="#资产清理与避坑" aria-label="Permalink to &quot;资产清理与避坑&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">资产与订阅</th><th style="text-align:left;">处置结果</th><th style="text-align:left;">必做处理</th></tr></thead><tbody><tr><td style="text-align:left;">云端对话与环境</td><td style="text-align:left;"><strong>30 天内</strong>物理擦除，快照销毁</td><td style="text-align:left;">提前导出代码和对话，下载文件</td></tr><tr><td style="text-align:left;">本地文件</td><td style="text-align:left;">完好无损</td><td style="text-align:left;">无需处理</td></tr><tr><td style="text-align:left;">商店与 X 独立订阅</td><td style="text-align:left;"><strong>不会自动取消</strong></td><td style="text-align:left;">需去 Apple、Google 或 x.ai 手动退订</td></tr></tbody></table><h2 id="获取官方支持与工单规范" tabindex="-1">获取官方支持与工单规范 <a class="header-anchor" href="#获取官方支持与工单规范" aria-label="Permalink to &quot;获取官方支持与工单规范&quot;">​</a></h2><h3 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h3><p>本地排查没用时，发邮件到 <strong><a href="mailto:hi@cursor.com" target="_blank" rel="noreferrer">hi@cursor.com</a></strong>。<strong>别只发“我的 Bot 坏了”这类模糊描述</strong>，邮件里带齐这六项。</p><ol><li>账号凭证：注册邮箱。</li><li>运行环境：平台与客户端版本号。从账户菜单 &gt; 支持 &gt; 关于，点 Copy version info 复制。</li><li>准备执行的操作：说明故障前想跑什么任务。</li><li>真实报错凭据：完整错误弹窗、控制台报错或计费截图。</li><li>排查记录：写明做过哪些排查，避免客服给重复建议。</li><li>Request ID：右键报错消息或悬停点 More message actions 选 Copy request ID。若没有该项，必须附原始报错文本与全屏截图。</li></ol><p>Linux 若弹 Update required 且自动更新失败，按发行版在终端执行更新指令：</p><ul><li>Debian / Ubuntu：<code>sudo apt update &amp;&amp; sudo apt install --only-upgrade grok-bot</code></li><li>Fedora / RPM 系列：<code>sudo dnf upgrade --refresh grok-bot</code></li></ul><details class="details custom-block"><summary>怎么做</summary><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>收件人：hi@cursor.com</span></span>
<span class="line"><span>主题：【Grok Bot 故障申报】云端电脑持续重连且 Recover 失败 - [你的账号邮箱]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>支持团队：</span></span>
<span class="line"><span>我的账号遇到了云端电脑无法连通的故障，无法正常执行任务，以下是详细环境与排查信息：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 账号邮箱：developer@example.com</span></span>
<span class="line"><span>2. 版本信息：Version 1.2.4 (Channel: stable, OS: Darwin x64 23.4.0)</span></span>
<span class="line"><span>3. 故障发生场景：我尝试让 Bot 运行自动化部署脚本，终端在拉取镜像时中断。</span></span>
<span class="line"><span>4. 核心报错信息：界面持续提示“Couldn&#39;t Reach Grok Bot&#39;s Computer”，伴随“Bot failed to respond”。</span></span>
<span class="line"><span>5. 已尝试的排错操作：</span></span>
<span class="line"><span>   - 已彻底 Quit 应用并重启；</span></span>
<span class="line"><span>   - 尝试在“设置 &gt; 计算机”执行 Update，提示备份未就绪；</span></span>
<span class="line"><span>   - 尝试点击 Recover，重试一次后依然在进度条处卡住报错；</span></span>
<span class="line"><span>   - 查看 status.cursor.com 确认官方各项服务状态正常。</span></span>
<span class="line"><span>6. 请求 ID (Request ID)：req_98af7c32e01b44d7a1</span></span>
<span class="line"><span>7. 附件：包含当前报错卡片截图及“设置 &gt; 计算机”面板状态截图。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请协助在后台检查该实例的宿主节点状态，谢谢。</span></span></code></pre></div></details><h3 id="做到什么程度算好" tabindex="-1">做到什么程度算好 <a class="header-anchor" href="#做到什么程度算好" aria-label="Permalink to &quot;做到什么程度算好&quot;">​</a></h3><p><strong>发信后能收到自动回执，且技术无需二次追问即可调出日志</strong>。详细规范见<a href="https://cursor.com/cn/help/grok-bot/get-help.md" target="_blank" rel="noreferrer">获取帮助</a>。</p><h2 id="典型故障排错案例" tabindex="-1">典型故障排错案例 <a class="header-anchor" href="#典型故障排错案例" aria-label="Permalink to &quot;典型故障排错案例&quot;">​</a></h2><h3 id="案例一-云端电脑-reconnecting-循环" tabindex="-1">案例一：云端电脑 Reconnecting 循环 <a class="header-anchor" href="#案例一-云端电脑-reconnecting-循环" aria-label="Permalink to &quot;案例一：云端电脑 Reconnecting 循环&quot;">​</a></h3><p>报 Couldn&#39;t Reach Grok Bot&#39;s Computer 时，<strong>千万别先点破坏性的 Reset</strong>。</p><ol><li>访问 <a href="https://status.cursor.com" target="_blank" rel="noreferrer">status.cursor.com</a> 确认服务正常，按 <code>Cmd+Q</code> 重启应用。</li><li>进设置 &gt; 计算机，若提示未及时暂停，等约 5 分钟让后台超时。</li><li>待 Recover 电脑亮起后点击恢复并重跑安装脚本，<strong>保全历史脚本与登录态</strong>。</li></ol><h3 id="案例二-slack-触发器用量雪崩" tabindex="-1">案例二：Slack 触发器用量雪崩 <a class="header-anchor" href="#案例二-slack-触发器用量雪崩" aria-label="Permalink to &quot;案例二：Slack 触发器用量雪崩&quot;">​</a></h3><p>因监听 3000 多人的 <code>#general</code> 全量闲聊，每周用量在 24 小时内归零。</p><ol><li><strong>先在支出面板设死按需月度限额</strong>，防止信用卡扣费。</li><li>将例程切为 Paused 止血。</li><li>规则收窄为“仅在 <code>#bot-help</code> 且被 <code>@Grok</code> 时触发”。</li><li>点 Test 单次验证后再恢复上线。</li></ol><h3 id="案例三-notion-认证失效与接管登录" tabindex="-1">案例三：Notion 认证失效与接管登录 <a class="header-anchor" href="#案例三-notion-认证失效与接管登录" aria-label="Permalink to &quot;案例三：Notion 认证失效与接管登录&quot;">​</a></h3><p>Notion 报 Action needed 且 Okta SSO 拦截时，<strong>必须用 Take over 在内置浏览器闭环认证</strong>。</p><ol><li>见 Needs auth 提示后，点击卡片中的 Take over 接管。</li><li>在云端内置浏览器输工号过二次验证，点 I&#39;m done。</li><li>在 Accounts 点 Add Another Account 授权个人空间，<strong>打上“个人库”标签防凭证冲突</strong>。</li></ol><h2 id="容易踩的坑" tabindex="-1">容易踩的坑 <a class="header-anchor" href="#容易踩的坑" aria-label="Permalink to &quot;容易踩的坑&quot;">​</a></h2><ol><li>丢聊天别点 Reset，会抹掉代码。找回先<strong>退出重启</strong>，核对 Cursor 账号或看隐藏机器人。</li><li>14:05 设 14:00 例程次日才跑，测逻辑点 <strong>Test</strong>。</li><li>Slack 大群无触发词监听，打招呼会<strong>烧光整周额度</strong>。</li><li>删 App 仍会扣费，退订去 <strong>Apple ID 或 Google Play</strong> 订阅中心取消。</li><li>Updating 时点 Reset 会<strong>损坏文件系统</strong>，只能找人工。</li><li>插件 Added 需确认 <strong>Connected</strong>；显示 Needs auth 需浏览器授权。</li><li>更新、Recover 或 Reset 清空 <code>node_modules</code> 与 <code>.venv</code>，依赖写进<strong>初始化脚本</strong>。</li><li>审批卡片 <strong>10 分钟后 Expired 终止</strong>，记得开通知或设“始终允许”。</li></ol><h2 id="做完怎么验收" tabindex="-1">做完怎么验收 <a class="header-anchor" href="#做完怎么验收" aria-label="Permalink to &quot;做完怎么验收&quot;">​</a></h2><ul><li>查 <a href="https://status.cursor.com" target="_blank" rel="noreferrer">status.cursor.com</a> 无故障且邮箱正确。</li><li>进设置 &gt; 计算机看绿灯，给 Bot 发基础 Linux 命令测回包。</li><li>例程保持激活，核对 When to run 时区，点 Test 跑通。</li><li>进设置 &gt; 用量与计费，<strong>必须设定按需用量月度限额</strong>防天价账单。</li><li>连接应用显 Connected，写操作能弹 Auto-review 且手机有推送。</li><li>工单只留 Request ID 和 Copy version info，<strong>切勿泄露 Bearer Token 请求头</strong>。</li></ul><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>相关章节：<a href="/part1/05-computer">第 5 章 共享云电脑：文件、浏览器与接管</a></li><li>相关章节：<a href="/part1/10-usage">第 10 章 额度与成本：让一周用量撑满一周</a></li><li><a href="https://cursor.com/cn/help/grok-bot/faqs" target="_blank" rel="noreferrer">Grok Bot 常见问题官方解答</a></li><li><a href="https://cursor.com/cn/help/grok-bot/how-to" target="_blank" rel="noreferrer">Grok Bot 操作与排错指南</a></li><li><a href="https://cursor.com/cn/help/grok-bot/computer-recovery" target="_blank" rel="noreferrer">Grok Bot 电脑环境管理与灾难恢复</a></li><li><a href="https://cursor.com/cn/help/grok-bot/routines" target="_blank" rel="noreferrer">自动化例程与触发器详细配置</a></li><li><a href="https://cursor.com/cn/help/grok-bot/delete-account" target="_blank" rel="noreferrer">账号体系与注销说明</a></li><li><a href="https://cursor.com/cn/help/grok-bot/get-help" target="_blank" rel="noreferrer">支持团队联系与工单规范</a></li><li><a href="https://cursor.com/cn/docs/grok-bot/settings" target="_blank" rel="noreferrer">Grok Bot 系统全局设置参考</a></li></ul>`,92)])])}const m=e(d,[["render",h]]);export{f as __pageData,m as default};
